"""Validate public HTML generated by the pinned Zensical build.

This intentionally tests the output, not only the Markdown source: a successful
build alone does not guarantee a populated tag listing.
"""
from pathlib import Path

SITE = Path("site")
tag_page = SITE / "tags" / "index.html"
assert tag_page.is_file(), "Missing published /tags/ page"
html = tag_page.read_text(encoding="utf-8")

# The tag listing must contain a generated link to each published lineage page.
for slug in ("chikuzen", "buzen", "takanabe", "ogi"):
    target = f"lineages/{slug}/"
    assert target in html, f"Missing generated lineage listing: {target}"

for name in ("筑前千手氏", "豊前香春千手氏", "日向高鍋千手氏", "肥前小城千手氏"):
    assert name in html, f"Missing visible tag label: {name}"

overview = SITE / "senju" / "index.html"
assert overview.is_file(), "Missing /senju/ overview"
overview_html = overview.read_text(encoding="utf-8")
for slug in ("chikuzen", "buzen", "takanabe", "ogi"):
    assert f"lineages/{slug}/" in overview_html, f"Missing wiki-style link to {slug}"

print("Validated tag listings and four lineage links.")
